def _nombres_que_sabe_escribir(txt):
    """Los patrones de nombre que este script ESCRIBE, con el %s adentro.

    NOMBRAR UN ARCHIVO NO ES ESCRIBIRLO, y esa diferencia es todo el gate: `pdf_entrega.py`
    nombra los siete prometidos (es el que los promete) y tiene verbos de escritura en otras
    partes del archivo, asi que con un "¿aparece el nombre? ¿hay un write en algun lado?"
    contaba como generador de todos -- y entonces ninguno quedaba huerfano y el control no
    podia dar rojo NUNCA. Se pide que la escritura este PEGADA al nombre: en las lineas de al
    lado, o sobre la variable a la que se le asigno la ruta, que es como lo hace
    step_tren_a_la_vista.py (`SAL = OUT + "/...step"` arriba, `nueva.export(SAL)` abajo)."""
    ln = txt.split("\n")
    fuera = set()

    def _cerca(i, var):
        if any(ESCRIBE.search(ln[k]) for k in range(max(0, i - 2), min(len(ln), i + 3))):
            return True
        return bool(var) and any(ESCRIBE.search(l) and re.search(r"\b%s\b" % var, l)
                                 for l in ln)

    for i, l in enumerate(ln):
        mv = re.match(r"\s*([A-Za-z_][A-Za-z0-9_]*)\s*=", l)
        var = mv.group(1) if mv else None
        for m in re.finditer(r'cfg\.salida\(\s*"([a-z_0-9]+)"\s*,\s*"([a-z]+)"'
                             r'(?:\s*,\s*"([^"]*)")?', l):
            if _cerca(i, var):
                fuera.add("%s_%%s%s.%s" % (m.group(1), m.group(3) or "", m.group(2)))
        for m in re.finditer(r'"[^"]*?/([A-Za-z0-9_%.]+\.(?:step|stl|dxf|pdf|gif))"', l):
            if _cerca(i, var):
                fuera.add(m.group(1))
    return fuera
